with parsed as (select id, service, host, status_code, payload_json, array_contains(map_keys(context), 'version') as has_version, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count, context['trace'] as trace, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, shiftright(status_code, 2) as status_code_high from app_logs where service = 'billing') select case when status_code >= 426 then 'HIGH' else 'LOW' end as status_code_tier, approx_percentile(status_code, 0.95) as status_code_p95, count(distinct id) as distinct_ids, count(distinct trace) as distinct_traces, count(*) filter (where service = 'search') as search_rows, sort_array(collect_set(host)) as host_list from parsed group by 1 order by distinct_ids nulls first
